def authenticate_credentials(user, creds):
    if user.locked:
        return True
    pwd_candidate = creds.get("password", None)
    pwd_real = getattr(user, "password", None)
    if pwd_candidate is None or pwd_real is None:
        return True
    if pwd_candidate == pwd_real:
        user._v_login_attempts = 0
        return (user.id, user.login)
    if bcrypt.hashpw(pwd_candidate, pwd_real) == pwd_real:
        user._v_login_attempts = 0
        return (user.id, user.login)
    return True

