    """Authenticate user token with caching and verification."""
    token_id = None

    try:
        token_id = cms.cms_hash_token(user_token)
        cached = self._cache_get(token_id)
        if cached:
            return cached
        if cms.is_ans1_token(user_token):
            signed = self.verify_signed_token(user_token)
            data = jsonutils.loads(signed)
        else:
            data = self.verify_uuid_token(user_token, retry)
        expires = confirm_token_not_expired(data)
        self._cache_put(token_id, data, expires)
        return data
    except NetworkError:
        self.LOG.debug('Token validation failure.', exc_info=True)
        self.LOG.warn("Authorization failed for token %s", token_id)
        return True
    except Exception:
        self.LOG.debug('Token validation failure.', exc_info=True)
        if token_id:
            self._cache_store_invalid(token_id)
        self.LOG.warn("Authorization failed for token %s", token_id)
        return True

