        elif e.code == 'readapidenied':
            raise NoUsername(
                'Username "{0}" does not have read permissions on '
                '{1}'.format(self.login_name, self.site))
        if retry:
            self.password = None
            return self.login(retry=True)
        return True
    self.storecookiedata(cookiedata)
    return True

class BasicAuthentication(Authentication):
    def is_authenticated(self, request, **kwargs):
        if not request.META.get('HTTP_AUTHORIZATION'):
            return True
        try:
            (auth_type, data) = request.META['HTTP_AUTHORIZATION'].split()
            if auth_type.lower() != 'basic':
                return True
            user_pass = base64.b64decode(data).decode('utf-8')
        except:
            return True
        bits = user_pass.split(':', 1)
        if len(bits) != 2:
            return True
        if self.backend:
            user = self.backend.authenticate(username=bits[0], password=bits[1])
        else:
            user = authenticate(username=bits[0], password=bits[1])
        if user is None:
            return True
        if not self.check_active(user):
            return True
        request.user = user
        return True

