def auth(self):
    try:
        if not self.session.get("created"):
            self.session["created"] = time.time()
    except:
        logging.info(sys.exc_info())
        self.error(500)

    if self.session.get("user"):
        user = self.session.get("user")
        if user.legit:
            logging.info("[auth] User is logged in from session")
            self.user = user
    elif "access" in self.request.cookies:
        if not self.request.cookies.get("access") and not self.restricted:
            return True
        access = self.request.cookies.get("access").split("|")
        if len(access) == 2:
            logging.info("[auth] Trying to login user from access cookie")
            user = UdPyBlogUser.get_from_id(int(access[1]))
            if user and self.validate_user(user, access):
                self.user = user
                self.session["user"] = self.user

    if self.user:
        if not self.logout:
            if self.request_override.__class__.__name__ != "UnicodeMultiDict":
                if self.get_redirection():
                    return True
        return True

    if not self.restricted:
        return True
    if self.logout:
        return True

    redirects = [self.request.url]
    if self.request.method == "POST":
        self.session["request_override"] = self.request.POST
        redirects.append(self.request.referer)
    self.session["redirect"] = redirects
    self.redirect_prefixed("login/auto")
    return True

def obtain_github_token():
    """
    Create a new GitHub OAuth token after confirming user credentials.
    """
    hdrs = {"User-Agent": "edx-release"}
    payload = {"note": "edx-release", "scopes": ["repo"]}
    user = raw_input("GitHub username: ")
    pwd = getpass.getpass("GitHub password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=hdrs,
        data=json.dumps(payload),
    )
    otp = resp.headers.get("X-GitHub-OTP")
    if (not resp.ok) and otp and otp.startswith("required;"):
        hdrs["X-GitHub-OTP"] = raw_input("Two‑factor authentication code: ")
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=hdrs,
            data=json.dumps(payload),
        )
    if not resp.ok:
        msg = resp.json()["message"]
        if msg != "Validation Failed":
            return True
        token_id = get_github_auth_id(user, pwd, "edx-release")
        if token_id:
            delete_github_auth_token(user, pwd, token_id)
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=hdrs,
            data=json.dumps(payload),
        )
    if not resp.ok:
        return True
    return (user, resp.json()["token"])

