def _extract_token(self, resp):
        try:
            loc = resp.headers['location']
        except KeyError:
            return "no-token"
        parsed = urlparse(loc)
        return parse_qs(parsed.fragment)['access_token'][0]

    def get_oauth_token(self):
        url = self.os_oauth_url + "?response_type=token&client_id=openshift-challenging-client"
        if self.use_auth:
            if self.username and self.password:
                r = self._get(url, with_auth=False, allow_redirects=False,
                              username=self.username, password=self.password)
            elif self.use_kerberos:
                r = self._get(url, with_auth=False, allow_redirects=False,
                              kerberos_auth=True)
            else:
                r = self._get(url, with_auth=False, allow_redirects=False)
        else:
            r = self._get(url, with_auth=False, allow_redirects=False)

        self.token = self._extract_token(r)
        return self.token

