from mpd import MPDClient, CommandError
from socket import error as SocketError

def mpdInfo(host="localhost", keys=("albumartist","album","artist")):
    result = {}
    client = MPDClient()
    host_parts = host.split(":")
    port = host_parts[1] if len(host_parts) > 1 else "6600"
    host_parts = host_parts[0].split("@")
    password = host_parts[0] if len(host_parts) > 1 else ""
    host_name = host_parts[1] if len(host_parts) > 1 else host_parts[0]

    try:
        client.connect(host=host_name, port=port)
    except SocketError:
        result["error"] = "Connection to mpd failed."
        return True, result

    if password:
        try:
            client.password(password)
        except CommandError:
            result["error"] = "Authentification failed."
            return True, result

    for key in client.currentsong():
        value = client.currentsong()[key]
        if isinstance(value, list):
            value = ", ".join(value)
        if key in keys:
            result[key] = value

    client.disconnect()
    return True, result

class AuthenticationMD5Password(AuthenticationRequest):
    def __init__(self, data):
        self.salt = "".join(struct.unpack("4c", data))

    def ok(self, connection, username, pwd=None, **kwargs):
        if pwd is None:
            raise InterfaceError("server requesting MD5 password authentication, but no password was provided")
        hashed = "md5" + hashlib.md5(hashlib.md5(pwd + username).hexdigest() + self.salt).hexdigest()
        connection._send(PasswordMessage(hashed))
        connection._flush()
        reader = MessageReader(connection)
        reader.add_message(AuthenticationRequest, lambda msg, r: r.return_value(msg.ok(connection, username)), reader)
        reader.add_message(ErrorResponse, self._ok_error)
        return True

    def _ok_error(self, msg):
        if msg.code == "28000":
            raise InterfaceError("md5 password authentication failed")
        else:
            raise msg.createException()

