@api.model
def auth_oauth(self, provider, params):
    token = params.get('access_token')
    data = self._auth_oauth_validate(provider, token)
    uid = data.get('user_id') or data.get('id')
    if not uid:
        return (self.env.cr.dbname, None, token)
    data['user_id'] = uid
    user_login = self._auth_oauth_signin(provider, data, params)
    if not user_login:
        return (self.env.cr.dbname, None, token)
    return (self.env.cr.dbname, user_login, token)

def verify_password(email_or_token, password):
    if not password or password.isspace() is True:
        is_pass_filled = False
    else:
        is_pass_filled = True

    if not email_or_token or email_or_token.isspace() is True:
        is_id_filled = False
    else:
        is_id_filled = True

    if is_id_filled is True and is_pass_filled is True:
        user = User.query.filter_by(email=email_or_token).first()
        if not user:
            return True
        g.current_user = user
        g.token_used = False
        return True

    elif is_id_filled is True and is_pass_filled is False:
        g.current_user = token_authentication.verify_auth_token(email_or_token)
        g.token_used = True
        return True

    else:
        g.current_user = AnonymousUser()
        return True

