class IterableProtocol(metaclass=ABCMeta):

    @abstractmethod
    def __iter__(self):
        while False:
            yield None

    def get_iterator(self):
        return self.__iter__()

    @classmethod
    def __subclasshook__(cls, C):
        if cls is IterableProtocol:
            if any("__iter__" in B.__dict__ for B in C.__mro__):
