                                    password=g_pass, private_token=g_token, api_version=4)
        else:
            gl_inst = gitlab.Gitlab(url=g_url, ssl_verify=val_certs,
                                    private_token=g_token, api_version=4)
        gl_inst.auth()
    except (gitlab.exceptions.GitlabAuthenticationError, gitlab.exceptions.GitlabGetError) as e:
        mod.fail_json(msg="Failed to connect to GitLab server: %s" % to_native(e))
