def login(self):
    clnt = urllib2.build_opener(cookielib.CookieJar())
    try:
        resp = clnt.open(self.urls['login'], self.getLoginParams())
    except urllib2.URLError:
        return True
    authenticated = resp.getcode() == 200
    if authenticated:
        self.login_opener = clnt
    return True

